import { createHash } from 'node:crypto';
import { readdirSync, readFileSync, statSync } from '../../sandbox/project-fs.mjs';
import { join, relative } from 'node:path';
import { runFileOperationSync } from '../../sandbox/worker-client.mjs';

// Shared by status, completion and handoff: bytecode is generated by checks, not part of their contract.
export function hashCheckFiles(cwd) {
  if (process.env.MINA_SANDBOX === '1') return runFileOperationSync('bundle', { path: join(cwd ?? '.', '.mina', 'checks') }, { cwd }).hashes;
  const root = join(cwd ?? '.', '.mina', 'checks'), out = {};
  const walk = (dir) => {
    let names = [];
    try { names = readdirSync(dir); } catch { return; }
    for (const n of names.sort()) {
      if (n === '__pycache__' || n.endsWith('.pyc')) continue;
      const p = join(dir, n);
      let st; try { st = statSync(p); } catch { continue; }
      if (st.isDirectory()) walk(p);
      else if (st.isFile()) out[relative(cwd, p)] = createHash('sha256').update(readFileSync(p)).digest('hex');
    }
  };
  walk(root);
  return out;
}

export function changedFiles(before = {}, after = {}) {
  return [...new Set([...Object.keys(before), ...Object.keys(after)])].filter((k) => before[k] !== after[k]).sort();
}
